import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Card dimensions (scene units)
  const cardW = 2.4;
  const cardH = 3.2;
  const headerH = 0.08;
  const padding = 0.5;
  const borderWidth = 0.006;

  // Base card background
  const cardGeom = new THREE.PlaneGeometry(cardW, cardH);
  const cardMat = new THREE.MeshStandardMaterial({
    color: 0x16161d,
    metalness: 0,
    roughness: 1.0,
  });
  const cardMesh = new THREE.Mesh(cardGeom, cardMat);
  group.add(cardMesh);

  // Machined header strip
  const headerGeom = new THREE.PlaneGeometry(cardW, headerH);
  const headerMat = new THREE.MeshStandardMaterial({
    color: 0x16161d,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const headerMesh = new THREE.Mesh(headerGeom, headerMat);
  headerMesh.position.z = 0.01;
  headerMesh.position.y = cardH / 2 - headerH / 2;
  group.add(headerMesh);

  // Card border (thin hairline)
  const borderMat = new THREE.LineBasicMaterial({
    color: 0x2a2a33,
    linewidth: 0.5,
  });
  const borderPoints = [
    new THREE.Vector3(-cardW / 2, -cardH / 2, 0.01),
    new THREE.Vector3(cardW / 2, -cardH / 2, 0.01),
    new THREE.Vector3(cardW / 2, cardH / 2, 0.01),
    new THREE.Vector3(-cardW / 2, cardH / 2, 0.01),
    new THREE.Vector3(-cardW / 2, -cardH / 2, 0.01),
  ];
  const borderGeom = new THREE.BufferGeometry().setFromPoints(borderPoints);
  const borderLine = new THREE.Line(borderGeom, borderMat);
  group.add(borderLine);

  // Feature row separators
  const separatorMat = new THREE.LineBasicMaterial({
    color: 0x23232b,
    linewidth: 0.5,
  });
  for (let i = 0; i < 3; i++) {
    const sepY = (cardH / 2) - headerH - padding - 1.95 - (i * 0.375);
    const sepPoints = [
      new THREE.Vector3(-cardW / 2 + padding, sepY, 0.01),
      new THREE.Vector3(cardW / 2 - padding, sepY, 0.01),
    ];
    const sepGeom = new THREE.BufferGeometry().setFromPoints(sepPoints);
    const sepLine = new THREE.Line(sepGeom, separatorMat);
    group.add(sepLine);
  }

  const disposables = [cardGeom, cardMat, headerGeom, headerMat, borderGeom, borderMat, separatorMat];
  const textMeshes = [];

  // Layout tracking
  let currentY = cardH / 2 - headerH - padding;

  // Tier name: "ATELIER RESERVE"
  const tierNameMesh = ctx.fontAtlas.create({
    text: 'ATELIER RESERVE',
    fontSize: 20,
    fontWeight: 700,
    family: 'JetBrains Mono',
    color: 0xe8ecf2,
    letterSpacing: 0.08,
  });
  tierNameMesh.position.set(-cardW / 2 + padding, currentY, 0.02);
  group.add(tierNameMesh);
  textMeshes.push(tierNameMesh);

  currentY -= 0.6;

  // Price: "$480"
  const priceMesh = ctx.fontAtlas.create({
    text: '$480',
    fontSize: 62,
    fontWeight: 600,
    family: 'Lora',
    color: 0xe8ecf2,
    letterSpacing: -0.01,
  });
  priceMesh.position.set(-cardW / 2 + padding, currentY, 0.02);
  group.add(priceMesh);
  textMeshes.push(priceMesh);

  currentY -= 0.85;

  // Caption: "PER MONTH, BILLED ANNUALLY"
  const captionMesh = ctx.fontAtlas.create({
    text: 'PER MONTH, BILLED ANNUALLY',
    fontSize: 9,
    fontWeight: 400,
    family: 'JetBrains Mono',
    color: 0x8a8a9e,
    letterSpacing: 0.12,
  });
  captionMesh.position.set(-cardW / 2 + padding, currentY, 0.02);
  group.add(captionMesh);
  textMeshes.push(captionMesh);

  currentY -= 0.5;

  // Feature rows with staggered animation
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];

  features.forEach((featureText, idx) => {
    const featureMesh = ctx.fontAtlas.create({
      text: featureText,
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      color: 0xe8ecf2,
      letterSpacing: 0,
    });

    const featureY = currentY - (idx * 0.375);
    featureMesh.position.set(-cardW / 2 + padding, featureY, 0.02);
    featureMesh.position.y += 0.2; // Start offset for fade-up

    if (featureMesh.material) {
      featureMesh.material.transparent = true;
      featureMesh.material.opacity = 0;
    }

    const staggerDelay = 0.1 + idx * 0.08;
    gsap.to(featureMesh.position, {
      y: featureY,
      duration: 0.5,
      delay: staggerDelay,
      ease: 'power2.out',
    });
    if (featureMesh.material) {
      gsap.to(featureMesh.material, {
        opacity: 1,
        duration: 0.5,
        delay: staggerDelay,
        ease: 'power2.out',
      });
    }

    group.add(featureMesh);
    textMeshes.push(featureMesh);
  });

  // CTA Button with gradient
  const ctaButtonGeom = new THREE.PlaneGeometry(1.4, 0.36);
  const ctaButtonMat = new THREE.MeshStandardMaterial({
    color: 0xc1121f,
    emissive: 0xff2a38,
    emissiveIntensity: 1.5,
    metalness: 0.3,
    roughness: 0.4,
  });
  const ctaButton = new THREE.Mesh(ctaButtonGeom, ctaButtonMat);
  ctaButton.position.set(0, -cardH / 2 + padding + 0.18, 0.02);
  group.add(ctaButton);
  disposables.push(ctaButtonGeom, ctaButtonMat);

  // CTA Label
  const ctaLabelMesh = ctx.fontAtlas.create({
    text: 'JOIN THE RESERVE',
    fontSize: 13,
    fontWeight: 700,
    family: 'JetBrains Mono',
    color: 0x16161d,
    letterSpacing: 0.08,
  });
  ctaLabelMesh.position.copy(ctaButton.position);
  ctaLabelMesh.position.z = 0.03;
  group.add(ctaLabelMesh);
  textMeshes.push(ctaLabelMesh);

  // CTA click handler with press animation
  ctaButton.userData.handlers = {
    onClick: () => {
      gsap.to(ctaButton.scale, {
        x: 0.97,
        y: 0.97,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 0,
      });
    },
  };

  // Main card: weighted-settle entry animation
  group.scale.set(1.04, 1.04, 1.04);
  gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // Cleanup handler
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(ctaButton.scale);
    textMeshes.forEach(mesh => {
      gsap.killTweensOf(mesh.position);
      if (mesh.material) gsap.killTweensOf(mesh.material);
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });
    disposables.forEach(resource => resource.dispose());
  };

  group.userData.handlers = group.userData.handlers || {};

  return group;
}
